"concentration": `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 200" role="img" aria-labelledby="il-concentration-t" font-family="system-ui,sans-serif" font-size="11" fill="#1e293b"><title id="il-concentration-t">兩種莫耳濃度</title><text x="8" y="14" font-size="12" fill="#1d4ed8" font-weight="700">體積莫耳濃度 M</text><text x="8" y="28" font-size="10" fill="#475569">molarity（隨溫度變）</text><path d="M74 38V90A30 30 0 1 0 86 90V38" fill="#f0f9ff" stroke="#334155" stroke-width="1.5"/><path d="M75 60H85V91A29 29 0 1 1 75 91Z" fill="#bfdbfe"/><path d="M70 60L90 60" stroke="#dc2626" stroke-width="1.5"/><text x="94" y="63" font-size="10" fill="#dc2626">刻度線</text><path d="M96.4 130.5h0M64 106.4h0M92.1 124.6h0M86.1 112.6h0M83.8 121h0M82.9 108.4h0M77.5 115h0M88 131.9h0M96.2 119.2h0" stroke="#dc2626" stroke-width="5" stroke-linecap="round"/><text x="116" y="112" font-size="11" fill="#1d4ed8" font-weight="700">1 L</text><text x="116" y="125" font-size="10" fill="#1d4ed8">溶液</text><text x="80" y="170" font-size="11" fill="#0f172a" text-anchor="middle" font-weight="700">M = 溶質 mol ÷ 溶液 L</text><text x="80" y="186" font-size="10" fill="#475569" text-anchor="middle">1 mol 溶質配成 1 L → 1 M</text><path d="M160 24L160 192" stroke="#e2e8f0" stroke-width="1"/><text x="168" y="14" font-size="12" fill="#1d4ed8" font-weight="700">重量莫耳濃度 m</text><text x="168" y="28" font-size="10" fill="#475569">molality（不受溫度影響）</text><path d="M206 58V122Q206 126 210 126H266Q270 126 270 122V58" fill="#f0f9ff" stroke="#334155" stroke-width="1.5"/><rect x="207" y="76" width="62" height="49" fill="#bfdbfe"/><path d="M220 92h0M238 104h0M256 88h0M226 116h0M250 114h0M234 84h0M262 104h0M216 104h0M246 96h0" stroke="#dc2626" stroke-width="5" stroke-linecap="round"/><rect x="192" y="128" width="92" height="22" rx="4" fill="#e2e8f0" stroke="#334155"/><rect x="222" y="132" width="46" height="14" rx="2" fill="#0f172a"/><text x="245" y="143" font-size="10" fill="#4ade80" text-anchor="middle" font-weight="700">1.000 kg</text><text x="274" y="72" font-size="10" fill="#1d4ed8" font-weight="700">水 1 kg</text><text x="274" y="85" font-size="10" fill="#1d4ed8">（溶劑）</text><text x="240" y="170" font-size="11" fill="#0f172a" text-anchor="middle" font-weight="700">m = 溶質 mol ÷ 溶劑 kg</text><text x="240" y="186" font-size="10" fill="#475569" text-anchor="middle">1 mol 溶於 1 kg 水 → 1 m</text><circle cx="176" cy="116" r="3" fill="#dc2626"/><text x="176" y="108" font-size="10" fill="#dc2626" text-anchor="middle">溶質</text></svg>`,

"reaction-equation": `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 200" role="img" aria-labelledby="il-reaction-equation-t" font-family="system-ui,sans-serif" font-size="11" fill="#1e293b"><title id="il-reaction-equation-t">化學反應式與產率</title><text x="160" y="20" font-size="14" fill="#0f172a" text-anchor="middle" font-weight="700"><tspan fill="#dc2626">2</tspan>H₂ + O₂ → <tspan fill="#dc2626">2</tspan>H₂O</text><circle cx="30" cy="46" r="8" fill="#fff" stroke="#334155"/><circle cx="44" cy="46" r="8" fill="#fff" stroke="#334155"/><circle cx="30" cy="72" r="8" fill="#fff" stroke="#334155"/><circle cx="44" cy="72" r="8" fill="#fff" stroke="#334155"/><text x="66" y="64" font-size="14" fill="#0f172a" text-anchor="middle" font-weight="700">+</text><circle cx="90" cy="59" r="10" fill="#ef4444" stroke="#334155"/><circle cx="107" cy="59" r="10" fill="#ef4444" stroke="#334155"/><path d="M130 59L158 59" stroke="#334155" stroke-width="2"/><path d="M166 59L158 62.6L158 55.4Z" fill="#334155"/><circle cx="191" cy="63" r="7" fill="#fff" stroke="#334155"/><circle cx="217" cy="63" r="7" fill="#fff" stroke="#334155"/><circle cx="204" cy="54" r="10" fill="#ef4444" stroke="#334155"/><circle cx="249" cy="63" r="7" fill="#fff" stroke="#334155"/><circle cx="275" cy="63" r="7" fill="#fff" stroke="#334155"/><circle cx="262" cy="54" r="10" fill="#ef4444" stroke="#334155"/><text x="68" y="98" font-size="10" fill="#475569" text-anchor="middle">反應物 reactants</text><text x="233" y="98" font-size="10" fill="#475569" text-anchor="middle">產物 products</text><text x="160" y="116" font-size="10" fill="#0f172a" text-anchor="middle">紅色係數 coefficient 使兩邊原子數相等：H 4 = 4，O 2 = 2</text><path d="M8 124L312 124" stroke="#e2e8f0" stroke-width="1"/><text x="8" y="138" font-size="10" fill="#0f172a" font-weight="700">理論產率 theoretical yield：36.0 g</text><rect x="8" y="142" width="240" height="10" rx="3" fill="#93c5fd"/><text x="8" y="166" font-size="10" fill="#0f172a" font-weight="700">實際產率 actual yield：30.6 g</text><rect x="8" y="170" width="204" height="10" rx="3" fill="#fbbf24"/><rect x="212" y="170" width="36" height="10" rx="3" fill="none" stroke="#94a3b8" stroke-dasharray="2 2"/><text x="312" y="160" font-size="11" fill="#b45309" text-anchor="end" font-weight="700">產率</text><text x="312" y="176" font-size="13" fill="#b45309" text-anchor="end" font-weight="700">= 85%</text><text x="160" y="194" font-size="10" fill="#475569" text-anchor="middle">產率 = 實際 ÷ 理論 × 100%</text></svg>`,

